import { useEffect, useState } from 'react';
import type { LanguageCode } from '@lexpad/core';
import { Button } from '@/components/ui/Button.js';
import { Sheet } from '@/components/ui/Sheet.js';
import { Toggle } from '@/components/ui/Toggle.js';
import { notebooks as notebooksApi } from '@/api/endpoints.js';
import { isApiError } from '@/api/errors.js';
import { t } from '@/i18n/index.js';
import { platform } from '@/lib/platform/index.js';
import { listNotebooks, setActiveNotebook } from '@/db/repo.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { useSync } from '@/sync/store.js';
import { LanguagePicker } from '@/features/onboarding/LanguagePicker.js';
import { LANGUAGE_NAMES, MEANING_LANGUAGES, TARGET_LANGUAGES } from '@/features/settings/data.js';
import { Upgrade } from '@/features/billing/Upgrade.js';
import { freeSide, useBilling } from '@/features/billing/state.js';
import styles from './NewNotebookSheet.module.css';

type Step = 'target' | 'meaning' | 'name';

/**
 * Making a second notebook.
 *
 * Two things make this different from every other write in the app. It
 * goes to the server rather than to the outbox, because whether an account
 * may keep another notebook is the server's answer and a notebook written
 * locally against a refusal would sit in the queue for ever. And it is the
 * one place that has to talk about money before anything happens: the
 * screen says which it will be — free or Pro — while the languages are
 * still being chosen, so nobody fills a form in to be told no at the end.
 *
 * The questions come in the order onboarding asks them, because a learner
 * has answered them once already and the second time should feel familiar.
 */
export function NewNotebookSheet({
  startAt,
  onCreated,
  onClose,
}: {
  /**
   * The language to start on, when something already knows: a word in a
   * script none of the notebooks holds arrives here with its language
   * already worked out, and asking again would be asking somebody to
   * repeat themselves.
   */
  startAt?: LanguageCode;
  onCreated: (notebookId: string) => void;
  onClose: () => void;
}): React.JSX.Element {
  const [step, setStep] = useState<Step>(startAt === undefined ? 'target' : 'meaning');
  const [targetLang, setTargetLang] = useState<LanguageCode | undefined>(startAt);
  const [meaningLang, setMeaningLang] = useState<LanguageCode | undefined>();
  const [title, setTitle] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | undefined>();
  const [paywall, setPaywall] = useState(false);
  const notebooks = useLiveQuery(() => listNotebooks(), undefined, []);
  const first = (notebooks ?? []).length === 0;
  // Offered only where there is a choice to make. The first notebook is the
  // default because there is nothing else it could be, and a switch that
  // cannot be turned off is not a switch.
  const [makeDefault, setMakeDefault] = useState(false);

  const state = useBilling((s) => s.state);
  const ensure = useBilling((s) => s.ensure);
  useEffect(() => {
    ensure();
  }, [ensure]);

  // What this notebook will cost, decided the same way the server decides
  // it: a language Lexpad gives away is free whatever the plan, and
  // everything else is Pro once there is already a notebook.
  const free = freeSide(state, targetLang, meaningLang);
  const pro = state?.plan === 'pro';
  // A plan not read yet locks nothing: a Pro or trial account must not be
  // shown "part of Pro" for the moment before the answer, and the server's
  // refusal (402) still opens the plans if this guess was wrong.
  const included = free !== undefined || pro || state === null;

  if (paywall) {
    return (
      <Upgrade
        onClose={() => {
          setPaywall(false);
        }}
      />
    );
  }

  if (step === 'target') {
    return (
      <Sheet title={t('newNotebook.title')} onClose={onClose}>
        <div className={styles.body}>
          <p className={styles.lead}>{t('newNotebook.lead')}</p>
          <p className={styles.question}>{t('newNotebook.target')}</p>
          <LanguagePicker
            label={t('newNotebook.target')}
            codes={TARGET_LANGUAGES}
            value={targetLang}
            onPick={(code) => {
              setTargetLang(code);
              setStep('meaning');
            }}
          />
        </div>
      </Sheet>
    );
  }

  if (step === 'meaning') {
    return (
      <Sheet title={t('newNotebook.title')} onClose={onClose}>
        <div className={styles.body}>
          <p className={styles.question}>{t('newNotebook.meaning')}</p>
          <LanguagePicker
            label={t('newNotebook.meaning')}
            codes={MEANING_LANGUAGES}
            value={meaningLang}
            onPick={(code) => {
              setMeaningLang(code);
              setStep('name');
            }}
          />
          <button
            type="button"
            className={styles.back}
            onClick={() => {
              setStep('target');
            }}
          >
            {t('action.back')}
          </button>
        </div>
      </Sheet>
    );
  }

  const target = targetLang ?? 'en';
  const meaning = meaningLang ?? 'en';
  const suggested = t('newNotebook.namePlaceholder', { target: LANGUAGE_NAMES[target] });

  const create = (): void => {
    setBusy(true);
    setError(undefined);
    notebooksApi
      .create({
        title: title.trim() === '' ? suggested : title.trim(),
        targetLang: target,
        meaningLang: meaning,
        // The first notebook is the default whatever anybody ticks: there
        // is nothing else it could be.
        ...(first || makeDefault ? { isDefault: true } : {}),
      })
      .then(async (made) => {
        // The notebook exists on the server; this device has it once it
        // has pulled, and then it becomes the one the app is showing.
        await useSync.getState().syncNow();
        await setActiveNotebook(made.id);
        onCreated(made.id);
      })
      .catch((cause: unknown) => {
        setBusy(false);
        // The client's view of the plan can be a moment out of date, so the
        // server's refusal is the one that counts.
        if (isApiError(cause, 'needsPayment')) {
          setPaywall(true);
          return;
        }
        setError(isApiError(cause, 'offline') ? t('newNotebook.offline') : t('newNotebook.failed'));
      });
  };

  return (
    <Sheet title={t('newNotebook.title')} onClose={onClose}>
      <div className={styles.body}>
        <button
          type="button"
          className={styles.pair}
          onClick={() => {
            setStep('target');
          }}
        >
          <span className={styles.pairText}>
            {t('newNotebook.pair', {
              target: LANGUAGE_NAMES[target],
              meaning: LANGUAGE_NAMES[meaning],
            })}
          </span>
          <span className={styles.change}>{t('newNotebook.change')}</span>
        </button>

        <label className={styles.field}>
          <span className={styles.label}>{t('newNotebook.name')}</span>
          <input
            className={styles.input}
            value={title}
            dir="auto"
            placeholder={suggested}
            autoFocus
            maxLength={120}
            onChange={(event) => {
              setTitle(event.target.value);
            }}
          />
        </label>

        {/* Said before the button is pressed, never after. */}
        {free !== undefined && (
          <div className={styles.free}>
            <strong>{t('newNotebook.freePair')}</strong>
            <span>
              {t('newNotebook.freePairWhy', { language: LANGUAGE_NAMES[free.code as LanguageCode] })}
            </span>
          </div>
        )}
        {!included && (
          <div className={styles.locked}>
            <strong>{t('newNotebook.needsPro')}</strong>
            <span>{t('newNotebook.needsProWhy')}</span>
          </div>
        )}

        {/* What "default" will mean for this one, said while it is being
            made rather than discovered later. */}
        {first ? (
          <p className={styles.note}>{t('notebooks.defaultNew')}</p>
        ) : (
          <div className={styles.defaultBlock}>
            <div className={styles.defaultRow}>
              <span className={styles.defaultLabel}>{t('notebooks.makeThisDefault')}</span>
              <Toggle
                label={t('notebooks.makeThisDefault')}
                checked={makeDefault}
                onChange={setMakeDefault}
              />
            </div>
            <p className={styles.note}>{t('notebooks.makeThisDefaultWhy')}</p>
          </div>
        )}

        {error !== undefined && <p className={styles.error}>{error}</p>}

        {included ? (
          <Button block size="large" busy={busy} disabled={!platform.network.online} onClick={create}>
            {busy ? t('newNotebook.creating') : t('newNotebook.create')}
          </Button>
        ) : (
          <Button
            block
            size="large"
            onClick={() => {
              setPaywall(true);
            }}
          >
            {t('newNotebook.seePro')}
          </Button>
        )}
        {!platform.network.online && <p className={styles.note}>{t('newNotebook.offline')}</p>}
      </div>
    </Sheet>
  );
}
